} from "streamlit-component-lib"
import React, { ReactNode } from "react"
import * as ethers from "ethers" // used for connecting wallet

interface State {
  walletAddress: string // replaced from the template boilerplate, but the issue is the same even when State is not used
  isFocused: boolean
}

declare global { // needs to be defined for window.ethereum to work
  interface Window {
    ethereum: any;
  }
}

// function for getting user signature
async function getAccount() {
  var provider;
  var signer;
  provider = new ethers.providers.Web3Provider(window.ethereum, "any");
  // Prompt user for account connections
  const request = await provider.send("eth_requestAccounts", []);
