@nena05 -

This comment from me seems like the right solution:

> I think the right solution here is to use a uniqueified column name in all cases, not just the melted case.

I came up with an "evil approach" that can temporarily mitigate this limitation.
**Caution** - don't use it in any serious circumstances unless you know what are you doing
1. this is _AI generated code_
2. the hijacking method is not _safe and stable_

**Method Description**
1. Native Rendering: You render your Heatmap using the standard st.plotly_chart(). This ensures your chart flawlessly inherits Streamlit's latest features, toolbars, and dynamic Dark/Light theme switching. 
2. The Parasite Component: We dynamically generate a zero-height, transparent HTML/JS iframe (plotly_click_listener) and place it immediately below your chart.
3. DOM Hijacking: Once loaded, the JS inside the invisible iframe traverses the parent DOM tree upwards to find the closest Plotly container (.js-plotly-plot). It then directly hooks into Plotly's underlying .on('plotly_click') API to capture the event and send the coordinates back to Python.

**Example**
```
import os
import streamlit as st
import streamlit.components.v1 as components
import plotly.express as px
import numpy as np

# ==========================================
# 1. Component Initialization (Cached & I/O Optimized)
# ==========================================
@st.cache_resource
def get_plotly_listener_component():
    """
    Creates and caches the hidden listener component.
    Ensures the component's HTML file is written to disk ONLY ONCE 
    to prevent I/O bottlenecks during frequent reruns.
    """
    # Define a hidden directory for the component in the current working directory
    component_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), ".plotly_listener_component")
    index_path = os.path.join(component_dir, "index.html")

    # Write the HTML/JS payload only if it doesn't already exist
    if not os.path.exists(index_path):
        os.makedirs(component_dir, exist_ok=True)

        html_content = """
        <!DOCTYPE html>
        <html>
        <head>
        <script>
            // Streamlit component bidirectional communication API
            function sendMessageToStreamlitClient(type, data) {
                window.parent.postMessage({isStreamlitMessage: true, type: type, ...data}, "*");
            }

            function init() {
                sendMessageToStreamlitClient("streamlit:componentReady", {apiVersion: 1});
                sendMessageToStreamlitClient("streamlit:setFrameHeight", {height: 0}); // Make iframe completely invisible
            }

            function sendValue(value) {
                sendMessageToStreamlitClient("streamlit:setComponentValue", {value: value});
            }

            function bindEvents() {
                // 1. Locate this specific iframe within the parent Streamlit app
                const iframes = window.parent.document.querySelectorAll('iframe');
                let myIframe = null;
                for (let i = 0; i < iframes.length; i++) {
                    if (iframes[i].contentWindow === window) {
                        myIframe = iframes[i];
                        break;
                    }
                }
                if (!myIframe) return;

                // 2. Traverse the DOM upwards to find the immediately preceding Plotly chart
                let currentNode = myIframe;
                let targetPlot = null;

                while (currentNode && currentNode.tagName !== 'BODY') {
                    let prev = currentNode.previousElementSibling;
                    while (prev) {
                        if (prev.classList && prev.classList.contains('js-plotly-plot')) {
                            targetPlot = prev; 
                            break;
                        }
                        targetPlot = prev.querySelector('.js-plotly-plot');
                        if (targetPlot) break;
                        prev = prev.previousElementSibling;
                    }
                    if (targetPlot) break;
                    currentNode = currentNode.parentElement;
                }

                // 3. Hijack the native plotly_click event
                if (targetPlot && typeof targetPlot.on === 'function' && !targetPlot._hasStreamlitClickHacked) {
                    targetPlot._hasStreamlitClickHacked = true; // Prevent multiple bindings

                    targetPlot.on('plotly_click', function(data) {
                        if(data && data.points) {
                            const points = data.points.map(pt => ({
                                curveNumber: pt.curveNumber,
                                pointIndex: pt.pointIndex,
                                pointNumber: pt.pointNumber, // Heatmap row/col indices are stored here
                                x: pt.x,
                                y: pt.y,
                                z: pt.z
                            }));
                            // Send extracted data back to Python
                            sendValue(points);
                        }
                    });
                }
            }

            // Listen for Streamlit render events to bind/re-bind
            window.addEventListener("message", function(event) {
                if (event.data.type === "streamlit:render") { bindEvents(); }
            });

            // Fallback interval to catch asynchronously loaded charts
            setInterval(bindEvents, 500); 
        </script>
        </head>
        <body onload="init()" style="margin:0; padding:0; background: transparent;"></body>
        </html>
        """

        with open(index_path, "w", encoding="utf-8") as f:
            f.write(html_content)

    # Declare and return the reusable Streamlit custom component
    return components.declare_component(name="plotly_click_listener", path=component_dir)

# Initialize the component function globally
plotly_click_listener = get_plotly_listener_component()


# ==========================================
# 2. Application Logic & UI
# ==========================================
st.set_page_config(layout="wide")
st.title("Native Plotly Heatmap + Click Hijacking 🚀")

# Simulate a heavy, slow-loading main app
st.write("Because we use `@st.fragment`, clicking the chart will **NOT** cause this text or the entire page to reload. The performance is instant!")

# Wrap the interactive zone in a fragment so only this specific function reruns on click
@st.fragment
def heatmap_interactive_zone():
    st.markdown("### 👈 Click anywhere on the Heatmap")

    # A. Generate dummy Heatmap data
    np.random.seed(42)
    z_data = np.random.rand(8, 8)
    fig = px.imshow(z_data, text_auto=".2f")

    # B. Render natively (Perfectly inherits Dark/Light themes and toolbars)
    st.plotly_chart(fig, use_container_width=True, key="native_heatmap")

    # C. Mount the parasite listener immediately below the chart
    # The key is required to maintain the state of this specific listener
    clicked_data = plotly_click_listener(key="heatmap_listener_instance")

    # D. Handle the data sent back from JavaScript
    if clicked_data:
        pt = clicked_data[0]
        # For Heatmaps, the [row, col] indices are stored in 'pointNumber'
        row, col = pt.get("pointNumber", [None, None])
        val = pt.get("z")

        st.success(
            f"⚡ **Click Intercepted!**\n"
            f"- **Grid Index:** Row `{row}`, Col `{col}`\n"
            f"- **Value (Z):** `{val:.3f}`\n"
            f"- **Coordinates:** X=`{pt.get('x')}`, Y=`{pt.get('y')}`"
        )
    else:
        st.info("Awaiting user click...")

# Execute the isolated interactive zone
heatmap_interactive_zone()
```

